def solution(n):
    """
    Compute the factorial of a non-negative integer n using both a loop and recursion.

    Args:
    n (int): A non-negative integer (0 <= n <= 12)

    Returns:
    int: The factorial of n
    """
    # Iterative approach using a loop
    def iterative_factorial(n):
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

    # Recursive approach
    def recursive_factorial(n):
        if n == 0:
            return 1
        else:
            return n * recursive_factorial(n - 1)

    # Return the factorial using the recursive approach
    return recursive_factorial(n)

# Example usage:
print(solution(5))  # Output: 120
print(solution(0))  # Output: 1

