def solution(n):
    """
    Returns a list of strings representing the numbers from 1 to n with FizzBuzz substitutions.

    :param n: An integer (1 <= n <= 10^3)
    :return: A list of strings
    """
    result = []  
    for i in range(1, n + 1):  
        if i % 3 == 0 and i % 5 == 0:  
            result.append("FizzBuzz")  
        elif i % 3 == 0:  
            result.append("Fizz")  
        elif i % 5 == 0:  
            result.append("Buzz")  
        else:
            result.append(str(i))  

    return result

def solution(n):
    """
    Returns a list of strings representing the numbers from 1 to n with FizzBuzz substitutions.

    :param n: An integer (1 <= n <= 10^3)
    :return: A list of strings
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    result = []  
    for i in range(1, n + 1):  
        if i % 3 == 0 and i % 5 == 0:  
            result.append("FizzBuzz")  
        elif i % 3 == 0:  
            result.append("Fizz")  
        elif i % 5 == 0:  
            result.append("Buzz")  
        else:
            result.append(str(i))  
    return result

