def solution(num1, num2, operator):
    """
    Simulates a simple calculator with error handling.

    Args:
        num1 (float): The first operand.
        num2 (float): The second operand.
        operator (str): A single character string representing the operation to perform.

    Returns:
        float: The result of the arithmetic operation if valid.
        str: An error message if the operator is not recognized or if there is an attempt to divide by zero.
    """

    # First, we check if the operator is one of the four basic arithmetic operators
    if operator == "+":
        # If the operator is "+", we perform addition
        return float(num1 + num2)

    # We use elif for efficiency, so we don't have to check other conditions if one is met
    elif operator == "-":
        # If the operator is "-", we perform subtraction
        return float(num1 - num2)

    elif operator == "*":
        # If the operator is "*", we perform multiplication
        return float(num1 * num2)

    elif operator == "/":
        # If the operator is "/", we check for division by zero
        if num2 == 0:
            # If num2 is zero, we return an error message
            return "Error: Division by zero"
        else:
            # Otherwise, we perform division
            return float(num1 / num2)

    else:
        # If the operator is not one of the four basic arithmetic operators, we return an error message
        return "Error: Invalid operator"

