def solution(nums, target):
    """
    Searches for a target value in a rotated sorted array.

    Args:
    nums (list): A rotated sorted array of integers.
    target (int): The target value to search for.

    Returns:
    int: The index of the target value if found, -1 otherwise.
    """
    if not nums:
        return -1  # Edge case: empty array

    left, right = 0, len(nums) - 1  # Initialize binary search pointers

    while left <= right:
        mid = (left + right) // 2  # Calculate mid index

        if nums[mid] == target:
            return mid  # Target found, return index

        # If left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1  # Target in left half, move right pointer
            else:
                left = mid + 1  # Target in right half, move left pointer
        # If right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1  # Target in right half, move left pointer
            else:
                right = mid - 1  # Target in left half, move right pointer

    return -1  # Target not found

