    """
    This function calculates the factorial of a given non-negative integer n using recursion.

    Args:
    n (int): A non-negative integer (0 <= n <= 12)

    Returns:
    int: An integer representing the factorial of the input number n.
    """

    # Check if input is not an integer or is not within the specified range
    if not isinstance(n, int) or n < 0 or n > 12:
        if not isinstance(n, int):
            raise TypeError("Input must be an integer.")
        else:
            raise ValueError("Input must be a non-negative integer and not exceed 12.")

    # Base case: The factorial of 0 is defined as 1
    if n == 0:
        return 1

    # Recursive case: n! = n × (n - 1)!
    # We assume that the function works correctly for n - 1 and use it to calculate the factorial for n
    else:
        return n * solution(n - 1)

