def solution(grid):
    m, n = len(grid), len(grid[0])
    start = None
    end = None
    count = 0

    # Find start, end and count non-obstacle cells
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
            elif grid[i][j] == 2:
                end = (i, j)
            if grid[i][j] != -1:
                count += 1

    # Directions for moving up, down, left, right
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(x, y, visited):
        if (x, y) == end:
            return 1 if visited == count else 0
        res = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != -1 and (nx, ny) not in visited:
                res += dfs(nx, ny, visited | {(nx, ny)})
        return res

    return dfs(start[0], start[1], {start})

