def solution(s: str) -> int:
    n = len(s)

    # Create a 2D table to store whether s[i..j] is a palindrome or not
    is_palindrome = [[False]*n for _ in range(n)]

    # Initialize the table for substrings of length 1
    for i in range(n):
        is_palindrome[i][i] = True

    # Fill the table for substrings of length 2
    for i in range(n-1):
        if s[i] == s[i+1]:
            is_palindrome[i][i+1] = True

    # Fill the table for lengths greater than 2
    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j] and is_palindrome[i+1][j-1]:
                is_palindrome[i][j] = True

    # Create a DP table to store the minimum cuts needed
    dp = [float('inf')] * n
    dp[0] = 0

    # Fill the DP table
    for i in range(1, n):
        if is_palindrome[0][i]:
            dp[i] = 0
        else:
            for j in range(i):
                if is_palindrome[j+1][i] and dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1

    return dp[-1]

