def solution(n):
    """
    Returns all distinct solutions to the N-Queens puzzle.

    Args:
    n (int): The size of the chessboard.

    Returns:
    list: A list of solutions, where each solution is a list of strings representing the board configuration.

    Raises:
    ValueError: If n is less than 1.
    """
    if n < 1:
        raise ValueError("Input must be a positive integer")

    def is_valid(board, row, col):
        # Check if a queen can be placed at (row, col) without being threatened
        for i in range(row):
            if board[i][col] == 'Q':
                return False
            if col - (row - i) >= 0 and board[i][col - (row - i)] == 'Q':
                return False
            if col + (row - i) < n and board[i][col + (row - i)] == 'Q':
                return False
        return True

    def place_queens(n, row, board, result):
        # Recursively place queens on the board
        if row == n:
            result.append([''.join(row) for row in board])
            return
        for col in range(n):
            if is_valid(board, row, col):
                board[row][col] = 'Q'
                place_queens(n, row + 1, board, result)
                board[row][col] = '.'

    result = []
    board = [['.' for _ in range(n)] for _ in range(n)]
    place_queens(n, 0, board, result)
    return result

