import heapq

def solution(nums, k):
    min_heap = []

    for num in nums:
        if len(min_heap) < k:
            heapq.heappush(min_heap, num)
        elif num > min_heap[0]:
            heapq.heappop(min_heap)
            heapq.heappush(min_heap, num)

    return min_heap[0]

def solution(nums):
    # Count the frequency of each number using a dictionary
    freq_dict = {}
    for num in nums:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Sort the numbers based on frequency and value
    sorted_nums = sorted(nums, key=lambda x: (-freq_dict[x], x))

    return sorted_nums

