import functools

def solution(stones, k):
    n = len(stones)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + stones[i]

    @functools.lru_cache(None)
    def dp(i, j, k_remaining):
        if i == j:
            return 0
        if k_remaining == 1:
            return prefix_sum[j] - prefix_sum[i]

        min_cost = float('inf')
        for x in range(i + 1, j, k - 1):
            cost = dp(i, x, k - 1) + dp(x, j, 1)
            min_cost = min(min_cost, cost)
        return min_cost

    return dp(0, n, k)

