def solution(jobDifficulty, d):
    n = len(jobDifficulty)

    # If it's impossible to schedule d days with n jobs, return -1
    if n < d:
        return -1

    # Initialize dp with infinity
    dp = [[float('inf')] * (d + 1) for _ in range(n + 1)]

    # Base case: 0 jobs can be scheduled in 0 days with difficulty 0
    dp[0][0] = 0

    for j in range(1, d + 1):
        for i in range(j, n + 1):
            max_difficulty = 0
            for k in range(i, j - 1, -1):
                max_difficulty = max(max_difficulty, jobDifficulty[k - 1])
                dp[i][j] = min(dp[i][j], dp[k - 1][j - 1] + max_difficulty)

    return dp[n][d]

