    n = len(s)
    if n == 0:
        return 0

    # Function to check if a substring is a palindrome
    def is_palindrome(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    # Initialize DP table with maximum cuts (n-1)
    dp = [float('inf')] * n
    dp[0] = 0  # Base case: 0 cuts for a single character

    for i in range(1, n):
        if is_palindrome(0, i):
            dp[i] = 0
        else:
            # Check all substrings ending at i
            for j in range(i):
                # If substring s[j..i] is a palindrome
                if is_palindrome(j + 1, i):
                    # Update dp[i] if a better partition is found
                    dp[i] = min(dp[i], dp[j] + 1)

    return dp[-1]

