def solution(arr):
    n = len(arr)
    if n <= 1:
        return 0

    lis = []
    for num in arr:
        idx = binary_search(lis, num)
        if idx == len(lis):
            lis.append(num)
        else:
            lis[idx] = num

    return sum(arr) - sum(lis)

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

