def solution(arr):
    n = len(arr)
    # Initialize variables to keep track of the number of reversals
    reversals = 0
    # Initialize a variable to keep track of the direction of the current sequence
    direction = 0

    for i in range(n - 1):
        # Check if the current element is greater than the next one
        if arr[i] > arr[i + 1]:
            # If the direction is 1 (increasing), increment the reversals and reset the direction
            if direction == 1:
                reversals += 1
                direction = -1
            # If the direction is 0 (neutral), set the direction to -1 (decreasing)
            elif direction == 0:
                direction = -1
        # Check if the current element is less than the next one
        elif arr[i] < arr[i + 1]:
            # If the direction is -1 (decreasing), increment the reversals and reset the direction
            if direction == -1:
                reversals += 1
                direction = 1
            # If the direction is 0 (neutral), set the direction to 1 (increasing)
            elif direction == 0:
                direction = 1

    # If there are still elements out of order, increment the reversals
    if direction != 0:
        reversals += 1

    # The minimum number of sorting operations is the minimum between reversals and n - 1
    return min(reversals, n - 1)

