def solution(arr):
    def min_swaps_to_sort(arr):
        n = len(arr)
        arr_pos = [*enumerate(arr)]
        arr_pos.sort(key=lambda it: it[1])
        visited = {k: False for k in range(n)}
        ans = 0
        for i in range(n):
            if visited[i] or arr_pos[i][0] == i:
                continue
            cycle_size = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = arr_pos[j][0]
                cycle_size += 1
            if cycle_size > 0:
                ans += (cycle_size - 1)
        return ans

    return min_swaps_to_sort(arr)

