def solution(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0]*n for _ in range(m)]

    # Initialize the first cell
    dp[0][0] = 1 if grid[0][0] != 1 else 0

    # Initialize the first row
    for i in range(1, n):
        if grid[0][i] == 1:
            dp[0][i] = 0
        else:
            dp[0][i] = dp[0][i-1]

    # Initialize the first column
    for i in range(1, m):
        if grid[i][0] == 1:
            dp[i][0] = 0
        else:
            dp[i][0] = dp[i-1][0]

    # Fill in the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            elif grid[i][j] == 2:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

