    def test_stress_test(self):
        """Test the function with a large list of random numbers."""
        import random
        numbers = [random.randint(-1000, 1000) for _ in range(1000)]
        output = solution(numbers)
        for i, num in enumerate(numbers):
            if num < 0 or num == 0:
                self.assertEqual(output[i], "neither")
            elif num % 2 == 0:
                self.assertEqual(output[i], "even")
            else:
                is_prime = True
                if num > 1:
                    for j in range(2, int(num ** 0.5) + 1):
                        if num % j == 0:
                            is_prime = False
                            break
                    if is_prime:
                        self.assertEqual(output[i], "prime")
                    else:
                        self.assertEqual(output[i], "odd")
                else:
                    self.assertEqual(output[i], "odd")

