def solution(numbers):
    """
    This function classifies a list of integers into three categories: "even", "odd", or "prime".

    Parameters:
    numbers (list): A list of integers.

    Returns:
    list: A list of strings representing the classification for each number in the input list.
    """

    def is_prime(n):
        # Helper function to check if a number is prime.
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        max_divisor = int(n**0.5) + 1
        for d in range(3, max_divisor, 2):
            if n % d == 0:
                return False
        return True

    classifications = []
    for num in numbers:
        # Classify the number based on the given conditions.
        if num < 0 or num == 0:
            classifications.append("neither")
        elif num % 2 == 0:
            classifications.append("even")
        elif is_prime(num):
            classifications.append("prime")
        else:
            classifications.append("odd")

    return classifications

